// Shape of src/edit-data.ts (generated by build_edit.py). All positions are in frames.
import type {HeadPos} from './reelGeometry';
export type Sub = {from: number; len: number; text: string}; // shot-local frames
export type Rect = [number, number, number, number]; // x, y, w, h in % of frame

export type Shot = {
  start: number;
  len: number;
  src?: string; // under public/ (video)
  from?: number; // in-point inside `src`, seconds
  photo?: string; // under public/ (still)
  speed?: number;
  vol?: number; // source audio volume; absent = muted
  music?: boolean;
  subs?: Sub[];
  x?: number; // crop focus %, for fit 'cover'
  y?: number;
  zoom?: number; // extra scale past 'cover', anchored at x/y (crop in past letterboxed edges)
  fit?: 'cover' | 'blur';
  blur?: Rect[]; // privacy blur boxes
  chip?: {big: string; small: string};
  srcClip?: string; // provenance, not rendered
  trans?: 'cut' | 'fade' | 'whip' | 'zoom'; // entry transition (reels)
  box?: number; // reels: push the picture into a band from this % down, leaving a drawing panel above
  anns?: Ann[]; // shot-local annotations (reels); absolute copies live on ReelData
  // reels v2: the picture is a demo (src stays the voice, played as audio only) with a head bubble on top
  demo?: Demo;
  head?: Head;
};

// rect/rectTo: [x0, y0, x1, y1] fractions of the source (srcW x srcH); rect moves to rectTo over the shot
export type Demo =
  | {kind: 'video'; src: string; from: number; speed: number; x?: number; y?: number; zoom?: number}
  | {kind: 'crop'; src: string; from: number; srcW: number; srcH: number; rect: [number, number, number, number]; rectTo?: [number, number, number, number]; cy: number}
  | {kind: 'still'; photo: string} // the demo ran out before its line: its last frame, held
  | {kind: 'card'};

// VP9-alpha bubble video (d x 1.3d, circle at the bottom), placed by reelGeometry.headBox(pos)
export type Head = {src: string; from: number; pos: HeadPos; prevPos?: HeadPos};

export type CounterSpec = {from: number; to: number; max?: number; format?: 'min' | 'int' | 'dec1'; label: string};

export type Section = {start: number; len: number; title?: string; sub?: string; step?: number; counter?: CounterSpec; shots: Shot[]};

export type LongData = {
  fps: number;
  total: number;
  captions: 'top' | 'bottom';
  burnSubs?: boolean;
  intro?: {kicker?: string; title: string; subtitle?: string} | null;
  sections: Section[];
  listCard?: {start: number; len: number; title: string; rows: [string, string][]; photo?: string} | null;
  outro?: {start: number; len: number; photo?: string; columns: {title: string; numbered?: boolean; items: string[]}[]};
  credits?: {start: number; len: number; lines: [string, string][]; teaser?: string; photo?: string};
  post?: {start: number; len: number; shots: Shot[]};
  music: {file: string; volume: number; mode: 'bed' | 'broll' | 'duck'; runs: {start: number; len: number; songFrom: number; fadeIn?: number; fadeOut?: number}[]; fadeIn: number; fadeOut: number; duck?: [number, number][]; duckVolume?: number} | null;
};

export type ShortData = {
  fps: number;
  total: number;
  sections: {start: number; len: number; big?: string; small?: string; shots: Shot[]}[];
  end: {start: number; len: number; photo?: string; big?: string; small?: string};
  music: {file: string; startSec: number; volume: number} | null;
};

// YouTube thumbnail (1280x720). Panels are full-canvas images clipped into a diagonal split
// (1 panel = full bleed). cx/cy = focus point (0-1) that zoom scales around; dx/dy shift in %.
export type ThumbPanel = {src: string; cx?: number; cy?: number; zoom?: number; dx?: number; dy?: number};
export type ThumbData = {panels: ThumbPanel[]; title: string; badge?: string; kicker?: string};

// ---------------------------------------------------------------- reels (1080x1920 talking head)
// An annotation drawn in the empty space the speaker leaves beside them. Anchored in plan.json to
// SOURCE time of the clip it belongs to, so it survives silence-cutting; frames here are absolute.
export type Ann = {
  start: number;
  len: number;
  kind: 'note' | 'list' | 'ring' | 'arrow' | 'bar' | 'label';
  x: number; // anchor, % of frame (top-left for blocks, centre for ring/arrow)
  y: number;
  w?: number; // % of frame width, for blocks
  text?: string;
  items?: string[]; // list rows; a leading '*' marks the row as highlighted
  to?: [number, number]; // arrow end point, % of frame
  rotate?: number; // degrees, for the hand-drawn tilt
  color?: string; // defaults to the theme accent
  bars?: [string, number][]; // bar: [label, fraction 0-1]
  size?: number; // scale of text/card (ring/arrow: stroke), default 1; check_scripts allows 0.5-3
  noIntro?: boolean; // list continuing the previous list (same rows): drawn fully from frame 0 (build_edit sets it)
  noOutro?: boolean; // the next annotation continues this one: no fade-out (build_edit sets it)
};

export type ReelData = {
  id: string;
  slug: string;
  title: string;
  fps: number;
  total: number;
  hook?: {start: number; len: number; big: string; small?: string; items?: string[]} | null;
  shots: Shot[];
  anns: Ann[];
  end?: {start: number; len: number; big: string; small?: string; items?: string[]} | null;
  music: LongData['music'];
};
